   (Single orchestrator)

======================= */



const AppController = {

  init() {

    UIAdapter.init();



    const restored = Storage.load();

    if (restored) {

      this.restoreHistory();

    } else {

      this.sendBotMessage(

        "👑 Bienvenido a MaxiQueen OS. Soy tu asistente. ¿En qué puedo ayudarte hoy?"

