let pulse = 0;

let currentLevel = 0;

let gameState = "playing";

let selectedTower = null;

let movingUnits = [];



const canvas = document.getElementById("gameCanvas");

const ctx = canvas.getContext("2d");



canvas.width = window.innerWidth;

canvas.height = window.innerHeight - 120;



/* =======================

